-- 31_script_flow_editor.sql
-- 内容: 编排接口编辑器 — RS_M18 扩展接口 A12(保存编排步骤)/A13(新增编排接口)
-- 1. SC_M18_SAVE_SCRIPTFLOW C# 脚本源码注册到 tss_code_asset + RS_M18 A12
-- 2. SC_M18_CREATE_SCRIPTFLOW C# 脚本源码注册到 tss_code_asset + RS_M18 A13
-- 3. D0704 AI工具集字典补 update_script_flow_api / read_script_flow_api
-- 日期: 2026-07-19

-- ============================================================
-- 1. SC_M18_SAVE_SCRIPTFLOW — 保存编排接口步骤
-- ============================================================

INSERT INTO tss_code_asset (ID, ASSETTYPE, CODE, NAME, SOURCECODE, VERSION, REMARK, ISDELETED, MODULEPATH, CREATETIME)
SELECT 'ca_m18_save_sflow', 'csharp', 'SC_M18_SAVE_SCRIPTFLOW', '保存编排接口步骤',
,
1, 'RS_M18 A12: 保存编排接口步骤(APIPARAM=步骤JSON)', 0, '@/modules/RS_M18/SC_M18_SAVE_SCRIPTFLOW.cs', NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tss_code_asset WHERE CODE='SC_M18_SAVE_SCRIPTFLOW');

-- 同步旧表(兼容)
INSERT INTO tss_api_script (ID, SCRIPTCODE, SCRIPTNAME, SOURCECODE, VERSION, REMARK, ISDELETED)
SELECT 'as_m18_save_sflow', 'SC_M18_SAVE_SCRIPTFLOW', '保存编排接口步骤',
,
1, 'RS_M18 A12: 保存编排接口步骤(APIPARAM=步骤JSON)', 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tss_api_script WHERE SCRIPTCODE='SC_M18_SAVE_SCRIPTFLOW');

-- RS_M18 A12 moudleapi 行
SET @m18 = (SELECT ID FROM tss_moudle WHERE MODULECODE='RS_M18');
INSERT INTO tss_moudleapi (ID, MODULEID, APICODE, ACTIONCODE, APITYPE, PATHNAME, APINAME, SCRIPTCODE, ENTRYNUM)
SELECT 'ma_m18_a12', @m18, 'A12', 'saveScriptFlow', 'csharp', 'MAIN', '保存编排接口步骤', 'SC_M18_SAVE_SCRIPTFLOW', 12
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tss_moudleapi WHERE ID='ma_m18_a12');

-- ============================================================
-- 2. SC_M18_CREATE_SCRIPTFLOW — 新增编排接口行
-- ============================================================

INSERT INTO tss_code_asset (ID, ASSETTYPE, CODE, NAME, SOURCECODE, VERSION, REMARK, ISDELETED, MODULEPATH, CREATETIME)
SELECT 'ca_m18_create_sflow', 'csharp', 'SC_M18_CREATE_SCRIPTFLOW', '新增编排接口行',
,
1, 'RS_M18 A13: 创建APITYPE=script的moudleapi行(空步骤)', 0, '@/modules/RS_M18/SC_M18_CREATE_SCRIPTFLOW.cs', NOW()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tss_code_asset WHERE CODE='SC_M18_CREATE_SCRIPTFLOW');

-- 同步旧表(兼容)
INSERT INTO tss_api_script (ID, SCRIPTCODE, SCRIPTNAME, SOURCECODE, VERSION, REMARK, ISDELETED)
SELECT 'as_m18_create_sflow', 'SC_M18_CREATE_SCRIPTFLOW', '新增编排接口行',
,
1, 'RS_M18 A13: 创建APITYPE=script的moudleapi行(空步骤)', 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tss_api_script WHERE SCRIPTCODE='SC_M18_CREATE_SCRIPTFLOW');

-- RS_M18 A13 moudleapi 行
INSERT INTO tss_moudleapi (ID, MODULEID, APICODE, ACTIONCODE, APITYPE, PATHNAME, APINAME, SCRIPTCODE, ENTRYNUM)
SELECT 'ma_m18_a13', @m18, 'A13', 'createScriptFlow', 'csharp', 'MAIN', '新增编排接口行', 'SC_M18_CREATE_SCRIPTFLOW', 13
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tss_moudleapi WHERE ID='ma_m18_a13');

-- ============================================================
-- 3. D0704 AI工具集字典补 update_script_flow_api / read_script_flow_api
-- ============================================================
INSERT INTO tss_dictitem (ID, DICTID, ITEMNAME, ITEMVALUE, ENTRYNUM)
SELECT 'di_d0704_update_sflow', 'dict_d0704', '修改编排接口', 'update_script_flow_api', 6
FROM DUAL WHERE NOT EXISTS (
  SELECT 1 FROM tss_dictitem WHERE DICTID='dict_d0704' AND ITEMVALUE='update_script_flow_api'
);
INSERT INTO tss_dictitem (ID, DICTID, ITEMNAME, ITEMVALUE, ENTRYNUM)
SELECT 'di_d0704_read_sflow', 'dict_d0704', '读取编排接口', 'read_script_flow_api', 7
FROM DUAL WHERE NOT EXISTS (
  SELECT 1 FROM tss_dictitem WHERE DICTID='dict_d0704' AND ITEMVALUE='read_script_flow_api'
);
